<?php
namespace app\service;
class UpstreamHttpService{
 public static function resolvePublic(string $url,bool $refresh=false):?array{
  $p=parse_url($url);if(!$p||!in_array(strtolower($p['scheme']??''),['http','https'],true)||empty($p['host'])||isset($p['user'])||isset($p['pass']))return null;
  $host=strtolower($p['host']);if(in_array($host,['localhost','localhost.localdomain'],true))return null;
  $port=(int)($p['port']??(strtolower($p['scheme'])==='https'?443:80));if(!in_array($port,[80,443,8080,8443],true))return null;
  if(filter_var($host,FILTER_VALIDATE_IP)){$ips=[$host];}
  else{
   $rk='lumen:dns:'.hash('sha256',$host.':'.$port);$r=RedisService::connect();$cached='';
   if($r)try{$v=$r->get($rk);if(is_string($v))$cached=$v;}catch(\Throwable $e){}
   if(!$refresh&&$cached!==''&&filter_var($cached,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))return[$host,$cached,$port];
   $ips=[];foreach(@dns_get_record($host,DNS_A|DNS_AAAA)?:[] as $row){if(isset($row['ip']))$ips[]=$row['ip'];if(isset($row['ipv6']))$ips[]=$row['ipv6'];}
   if(!$ips)return null;foreach($ips as $ip)if(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))return null;
   if($r)try{$r->setex($rk,300,$ips[0]);}catch(\Throwable $e){}
  }
  if(!$ips)return null;foreach($ips as $ip)if(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))return null;return[$host,$ips[0],$port];
 }
 public static function send(string $url,string $method,array $headers=[],string $body='',int $timeout=30,int $maxBytes=5242880):array{$resolveStart=hrtime(true);$resolved=self::resolvePublic($url);$resolveMs=(hrtime(true)-$resolveStart)/1e6;if(!$resolved)throw new \RuntimeException('unsafe_target');[$host,$ip,$port]=$resolved;$buf='';$overflow=false;$transferStart=0;$finalHeaderMs=null;$ch=curl_init($url);$opts=[CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>min(10,$timeout),CURLOPT_TIMEOUT=>$timeout,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_PROTOCOLS=>CURLPROTO_HTTP|CURLPROTO_HTTPS,CURLOPT_RESOLVE=>[$host.':'.$port.':'.$ip],CURLOPT_MAXREDIRS=>0,CURLOPT_HEADER=>false,CURLOPT_TCP_KEEPALIVE=>1,CURLOPT_HEADERFUNCTION=>function($ch,$line)use(&$finalHeaderMs,&$transferStart){if(preg_match('#^HTTP/\S+\s+(\d+)#i',trim($line),$m)&&(int)$m[1]>=200)$finalHeaderMs=(hrtime(true)-$transferStart)/1e6;return strlen($line);},CURLOPT_WRITEFUNCTION=>function($ch,$chunk)use(&$buf,&$overflow,$maxBytes){if(strlen($buf)+strlen($chunk)>$maxBytes){$overflow=true;return 0;}$buf.=$chunk;return strlen($chunk);}];if(defined('CURL_HTTP_VERSION_2TLS'))$opts[CURLOPT_HTTP_VERSION]=CURL_HTTP_VERSION_2TLS;if($body!==''&&$method!=='GET')$opts[CURLOPT_POSTFIELDS]=$body;curl_setopt_array($ch,$opts);$transferStart=hrtime(true);$ok=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$ct=(string)curl_getinfo($ch,CURLINFO_CONTENT_TYPE);$err=curl_error($ch);$info=curl_getinfo($ch);$info['appconnect_time']=curl_getinfo($ch,CURLINFO_APPCONNECT_TIME);$timing=['resolve_ms'=>round($resolveMs,2),'connect_ms'=>round(max(0,($info['connect_time']??0)-($info['namelookup_time']??0))*1000,2),'tls_ms'=>round(max(0,($info['appconnect_time']??0)-($info['connect_time']??0))*1000,2),'wait_first_byte_ms'=>round(max(0,($finalHeaderMs!==null?$finalHeaderMs/1000:($info['starttransfer_time']??0))-($info['pretransfer_time']??0))*1000,2),'download_ms'=>round(max(0,($info['total_time']??0)-($finalHeaderMs!==null?$finalHeaderMs/1000:($info['starttransfer_time']??0)))*1000,2),'transfer_total_ms'=>round(($info['total_time']??0)*1000,2)];curl_close($ch);if($overflow)throw new \RuntimeException('response_too_large');if($ok===false)throw new \RuntimeException($err?:'upstream_failed');return['status'=>$status?:502,'content_type'=>$ct,'body'=>$buf,'timing'=>$timing];}
 public static function stream(string $url,string $method,array $headers,string $body,int $timeout,callable $onHeaders,callable $onChunk):array{$resolved=self::resolvePublic($url);if(!$resolved)throw new \RuntimeException('unsafe_target');[$host,$ip,$port]=$resolved;$status=0;$ct='text/event-stream';$sent=false;$ch=curl_init($url);$opts=[CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>min(5,$timeout),CURLOPT_TIMEOUT=>$timeout,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_PROTOCOLS=>CURLPROTO_HTTP|CURLPROTO_HTTPS,CURLOPT_RESOLVE=>[$host.':'.$port.':'.$ip],CURLOPT_MAXREDIRS=>0,CURLOPT_HEADER=>false,CURLOPT_TCP_KEEPALIVE=>1,CURLOPT_HEADERFUNCTION=>function($ch,$line)use(&$status,&$ct,&$sent,$onHeaders){$len=strlen($line);$t=trim($line);if(preg_match('#^HTTP/\\S+\\s+(\\d+)#i',$t,$m))$status=(int)$m[1];elseif(stripos($t,'content-type:')===0)$ct=trim(substr($t,13));elseif($t===''&&!$sent){$sent=true;$onHeaders($status?:200,$ct);}return$len;},CURLOPT_WRITEFUNCTION=>function($ch,$chunk)use($onChunk){$onChunk($chunk);return strlen($chunk);}];if(defined('CURL_HTTP_VERSION_2TLS'))$opts[CURLOPT_HTTP_VERSION]=CURL_HTTP_VERSION_2TLS;if($body!==''&&$method!=='GET')$opts[CURLOPT_POSTFIELDS]=$body;curl_setopt_array($ch,$opts);$ok=curl_exec($ch);$final=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$err=curl_error($ch);curl_close($ch);if($ok===false)throw new \RuntimeException($err?:'upstream_failed');return['status'=>$final?:($status?:200),'content_type'=>$ct];}
}
